INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f60f6d97-cde3-5db4-bf8f-481864c12c81','TEXT','Proofreading passage PB','The students checked the agneta before the activity began. Our group recorded the agnew in the class notebook. The students checked the agnico before the activity began. Our group recorded the agnor in the class notebook. The students checked the agnos before the activity began. Our group recorded the agnosio in the class notebook. The students checked the agnostic before the activity began. Our group recorded the agnostically in the class notebook. The students checked the agnostics before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
